def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    edges = s.get('neighbors') or []
    nearest = [inf] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    counts = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and d <= 1.25 * nearest[i]:
            counts[i] += occ[j]
    mean = sum(occ[i] * counts[i] for i in range(n)) / total
    return sqrt(max(0.0, sum(occ[i] * (counts[i] - mean) ** 2 for i in range(n)) / total))

