    return value / total

def feature(s):
    if not s:
        return 0.0
    vpa = s.get('volume_per_atom_A3')
    if vpa is not None and vpa > 0:
        return log(vpa)
    volume = (s.get('lattice') or {}).get('volume_A3')
    occupied = sum(max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in s.get('sites') or [])
    return log(volume / occupied) if volume is not None and volume > 0 and occupied > 0 else 0.0
